    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])

    # Count all values
    vals = [cell for row in grid for cell in row]
    counter = Counter(vals)

    # Background is most frequent
    bg = counter.most_common(1)[0][0]

    # Structure: most frequent non-background
    other = {k: v for k, v in counter.items() if k != bg}

    if not other:
        return [row[:] for row in grid]

    structure = max(other, key=other.get)

    # Seeds: remaining values
    seeds = [k for k in counter.keys() if k != bg and k != structure and counter[k] > 0]

    if not seeds:
        return [row[:] for row in grid]

    # Find what seed each parity maps to by checking seed positions
    seed_parity = {}
    # Seed parity: we need to find which parity (r+c)%2 a seed appears at
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] in seeds:
                parity = (r + c) % 2
                # Seed at this position maps parity to seed value
                seed_parity[parity] = grid[r][c]

    output = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == structure:
                parity = (r + c) % 2
                output[r][c] = seed_parity.get(parity, seeds[0])

    return output
